G=load()
def lines_of(I):
    H,W=len(I),len(I[0]); res=[]
    for i in range(H):
        row=I[i]
        segs=[]; j=0
        while j<W:
            if row[j]==0: j+=1; continue
            v=row[j]; s=j
            while j<W and row[j]==v: j+=1
            segs.append((s,j-1,v))
        # collapse touching same-color segments
        uniq=[]
        for s,e,v in segs:
            if uniq and e+1==uniq[-1][1] and v==uniq[-1][2]: uniq[-1]=(uniq[-1][0],e,v)
            else: uniq.append((s,e,v))
        if len(uniq)>=2:
            res.append((i,uniq))
    return res
def is_in_line(i,j,lins):
    for lr,segs in lins:
        if lr==i and any(s<=j<=e for s,e,v in segs): return True
    return False
def solve(I, debug=False):
    H,W=len(I),len(I[0]); O=[r[:] for r in I]
    lins=lines_of(I)
    # stray components: connected comps of nonzero cells not in any line row segment
    seen=[[False]*W for _ in range(H)]
    strays=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]!=0 and not seen[i][j] and not is_in_line(i,j,lins):
                stack=[(i,j)]; comp=[]; seen[i][j]=True; v=I[i][j]
                while stack:
                    a,b=stack.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and I[x][y]==v and not seen[x][y]:
                            seen[x][y]=True; stack.append((x,y))
                strays.append(comp)
    def paint(O,r,c,val):
        if 0<=r<H and 0<=c<W and O[r][c]==0: O[r][c]=val
    # strays first
    for comp in strays:
        cols=set(c for _,c in comp)
        for c in cols:
            cells=[r for r,_ in comp if _==c]
            below=[r for r in range(H) if is_in_line(r,c,lins)]
            above=[r for r in range(H) if is_in_line(r,c,lins)]
            def ext(start,step):
                r=start; 
                while True:
                    r+=step
                    if not(0<=r<H): break
                    if is_in_line(r,c,lins): break
                    paint(O,r,c,I[comp[0][0]][c] if False else O[comp[0][0]][0] if False else None)
                    break
            # simpler: walk from each stray cell
            for (a,b) in comp:
                # up
                r=a-1
                while r>=0 and not is_in_line(r,c,lins):
                    paint(O,r,c,I[a][b]); r-=1
                # down
                r=a+1
                while r<H and not is_in_line(r,c,lins):
                    paint(O,r,c,I[a][b]); r+=1
    # line extensions: top-to-bottom, paint only background
    for lr,segs in lins:
        for s,e,v in segs:
            # find gaps between consecutive same-color segments
            for k in range(len(segs)-1):
                a1,b1,v1=segs[k]; a2,b2,v2=segs[k+1]
                if v1==v2 and b1<a2-1:
                    gaps=list(range(b1+1,a2))
                    for g in gaps:
                        # up
                        r=lr-1
                        while r>=0 and not is_in_line(r,g,lins):
                            paint(O,r,g,v); r-=1
                        r=lr+1
                        while r<H and not is_in_line(r,g,lins):
                            paint(O,r,g,v); r+=1
    return O
